import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `rh-${String(++n).padStart(3, '0')}`;
const ex = (level) => (level <= 3 ? ['neet', 'cuet'] : ['neet']);
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: ex(level), sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: ex(level), sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: ex(level), sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: ex(level), sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: ex(level), sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function nat(level, sub, q, answer, sol, unit, trap, tol = 0) {
  items.push({ id: nid(), type: 'nat', level, format: tol ? 'numeric' : 'integer', exams: ex(level), sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
}

// ---------------------------------------------------------------- Level 1
mc(1, 'reproductive health', `According to the WHO, reproductive health means total well-being in`, `physical, emotional, behavioural and social aspects of reproduction`, [`only the physical health of reproductive organs`, `only the absence of sexually transmitted infections`, `only the ability to have children`], `Reproductive health is a wider idea than "no disease". It covers the body, the mind, behaviour and social life linked to reproduction. The other options each pick only one narrow part.`);
mc(1, 'programmes', `Family planning programmes in India were started in the year`, `1951`, [`1971`, `1947`, `1990`], `India was among the first countries to start national family planning action plans, in 1951. The year 1971 is when the MTP Act was passed.`);
mc(1, 'programmes', `The present programme of the Government of India that looks after reproductive health is called`, `Reproductive and Child Health Care (RCH)`, [`Pulse Polio Programme`, `Green Revolution Programme`, `Mid-day Meal Scheme`], `The family planning programme grew into the broader Reproductive and Child Health Care (RCH) programme. The others deal with polio, farming and school meals.`);
mc(1, 'contraception', `Which of the following is a barrier contraceptive?`, `Condom`, [`Copper-T`, `Vasectomy`, `Oral pill`], `A barrier method physically stops sperm from meeting the ovum. Condoms do this. Copper-T is an IUD, vasectomy is surgical and the pill is hormonal.`);
mc(1, 'contraception', `Copper-T is an example of`, `an intra-uterine device (IUD)`, [`an oral contraceptive`, `a surgical method`, `a barrier made of rubber`], `Copper-T is placed inside the uterus by a doctor or a trained nurse, so it is an IUD.`);
mc(1, 'contraception', `Saheli is a contraceptive pill that is taken`, `once a week`, [`once a day for 21 days`, `once a month after menstruation`, `within 72 hours of coitus`], `Saheli is a non-steroidal pill developed at the Central Drug Research Institute (CDRI), Lucknow. It is taken once a week (after the initial schedule). The 21-day daily course belongs to the combined hormonal pill.`);
mc(1, 'surgical', `In vasectomy, the part that is cut and tied is the`, `vas deferens`, [`fallopian tube`, `urethra`, `epididymis`], `Vasectomy is male sterilisation. A small cut is made in the scrotum and the vas deferens is cut and tied, so sperm cannot join the semen.`);
mc(1, 'surgical', `Tubectomy is the surgical sterilisation of`, `females, by cutting and tying the fallopian tubes`, [`males, by cutting the vas deferens`, `females, by removing the uterus`, `males, by removing the testes`], `In tubectomy a small cut is made in the abdomen or through the vagina, and the fallopian tubes are cut and tied. The ovum then cannot travel to meet sperm.`);
mc(1, 'MTP', `The Medical Termination of Pregnancy (MTP) was legalised in India in`, `1971`, [`1951`, `1947`, `1987`], `The MTP Act of 1971 allowed it with strict conditions so that it is not misused.`);
mc(1, 'MTP', `MTPs are considered relatively safe during`, `the first trimester, up to 12 weeks of pregnancy`, [`the second trimester only`, `the last 4 weeks of pregnancy`, `any time of pregnancy`], `As NCERT states, MTPs are safe up to 12 weeks (first trimester). The second trimester is much riskier.`);
mc(1, 'ART', `IVF stands for`, `in vitro fertilisation`, [`in vivo fertilisation`, `intra-venous fertilisation`, `internal vaginal fertilisation`], `In vitro means "in glass", that is, outside the body. In IVF the ovum and sperm are united in a laboratory dish.`);
mc(1, 'STI', `Which of the following is a sexually transmitted infection?`, `Gonorrhoea`, [`Typhoid`, `Malaria`, `Cholera`], `Gonorrhoea, syphilis, genital herpes and others are STIs. Typhoid, malaria and cholera spread through water, food or mosquitoes.`);
mc(1, 'amniocentesis', `Amniocentesis is a prenatal diagnostic technique that is used to test the foetus for`, `genetic and chromosomal disorders`, [`pregnancy hormones`, `blood groups of the mother`, `food allergies`], `A sample of the amniotic fluid contains cells of the foetus. They are tested for disorders such as Down syndrome, haemophilia and sickle-cell anaemia.`);
mc(1, 'amniocentesis', `Misuse of amniocentesis in India is mainly to`, `find the sex of the foetus, which can lead to female foeticide`, [`cure the foetus`, `increase the amount of amniotic fluid`, `prevent twin pregnancy`], `Because of the misuse for sex determination, there is a statutory ban on it in India.`);
mc(1, 'contraception', `Which of the following is a natural method of birth control?`, `Periodic abstinence`, [`Diaphragm`, `Tubectomy`, `Copper-T`], `Natural methods avoid meeting of sperm and ovum without any device or drug: periodic abstinence, withdrawal and lactational amenorrhea.`);
mc(1, 'contraception', `Lactational amenorrhea gives some protection against pregnancy for about`, `six months after delivery, if the mother feeds the baby fully`, [`two weeks after delivery`, `two years after delivery`, `the whole period of breast feeding, whatever its length`], `During intense lactation, ovulation does not occur and periods do not start. NCERT says this works only up to about six months after parturition.`);
mc(1, 'contraception', `In periodic abstinence, couples avoid sexual intercourse from which days of the menstrual cycle (counting the first day of bleeding as day 1)?`, `Day 10 to day 17`, [`Day 1 to day 5`, `Day 20 to day 28`, `Day 25 to day 30`], `Ovulation occurs about day 14, so days 10-17 are the fertile period. Avoiding intercourse then is the principle of this method.`);
mc(1, 'ART', `The technique in which a sperm is directly injected into an ovum is`, `ICSI`, [`GIFT`, `IUI`, `ZIFT`], `ICSI is intra-cytoplasmic sperm injection. GIFT and ZIFT are transfers into the fallopian tube, and IUI puts semen into the uterus.`);
mc(1, 'population', `A major reason for the rapid rise of world population is`, `a fall in death rate, maternal mortality rate and infant mortality rate`, [`a fall in birth rate`, `a rise in infant mortality rate`, `a fall in the number of people of reproductive age`], `Better health care lowered deaths while births stayed high. More people also reached reproductive age. This gave the population explosion.`);
mc(1, 'population', `The statutory marriageable age in India is`, `18 years for females and 21 years for males`, [`21 years for females and 18 years for males`, `18 years for both`, `25 years for males and 21 years for females`], `Raising the marriageable age is one measure to control the population. NCERT gives 18 years for females and 21 years for males.`);
mc(1, 'contraception', `Copper ions released by Cu-releasing IUDs`, `suppress sperm motility and the fertilising capacity of sperm`, [`stop ovulation`, `kill the ovum in the ovary`, `block the vas deferens`], `Copper ions in the uterus make it hostile to sperm. Ovulation-stopping is the job of the hormonal pill.`);

// ---------------------------------------------------------------- Level 2
mc(2, 'contraception', `Which of the following is NOT a feature of an ideal contraceptive?`, `It should cause permanent loss of fertility`, [`It should be user-friendly and easily available`, `It should be reversible`, `It should have no or the least side effects`], `An ideal contraceptive must be reversible, effective, easily available and must not interfere with sexual drive. Permanent loss of fertility is a feature of sterilisation, not of an ideal contraceptive.`);
mc(2, 'contraception', `Coitus interruptus (withdrawal) means that`, `the male withdraws the penis before ejaculation so semen does not enter the vagina`, [`the male wears a condom`, `the female is injected with progestogens`, `intercourse is avoided from day 10 to day 17`], `It is a natural method. Its weakness is that some pre-ejaculatory fluid or a late withdrawal can still allow pregnancy.`);
mc(2, 'contraception', `Which contraceptive also gives good protection against STIs and AIDS?`, `Condom`, [`Copper-T`, `Oral pill`, `Tubectomy`], `Condoms stop semen and body fluids from passing between partners, so they protect from many STIs. IUDs, pills and surgery do not form a barrier between partners.`);
mc(2, 'contraception', `Diaphragms, cervical caps and vaults are`, `reusable rubber barriers placed in the female reproductive tract to cover the cervix`, [`disposable sheaths worn on the penis`, `hormone-releasing devices`, `surgical instruments for sterilisation`], `They block the entry of sperm through the cervix. They are inserted into the female tract and, unlike condoms, are reusable.`);
mc(2, 'contraception', `Spermicidal creams, jellies and foams are usually used`, `along with barriers such as diaphragms, cervical caps and vaults`, [`along with oral pills`, `along with tubectomy`, `after intercourse as emergency contraceptive`], `They kill sperm, so together with barriers they raise the contraceptive effect.`);
mc(2, 'contraception', `Which of the following is a non-medicated IUD?`, `Lippes loop`, [`Cu7`, `Multiload 375`, `LNG-20`], `Lippes loop is plastic and releases nothing. Cu7 and Multiload 375 release copper. LNG-20 releases a hormone (levonorgestrel).`);
mc(2, 'contraception', `LNG-20 and Progestasert are`, `hormone-releasing IUDs`, [`copper-releasing IUDs`, `non-medicated IUDs`, `injectable contraceptives`], `Hormone-releasing IUDs release progestogens. They make the uterus unsuitable for implantation and the cervix hostile to sperm.`);
mc(2, 'contraception', `IUDs are ideal contraceptives for females who`, `want to delay pregnancy or space children`, [`want a permanent end to child-bearing`, `want protection from STIs`, `have never had sexual intercourse`], `IUDs are effective, reversible and long-acting, so they suit delaying or spacing births. Permanent methods are tubectomy and vasectomy.`);
mc(2, 'contraception', `A combined oral contraceptive pill is usually started`, `within the first five days of menstruation and taken daily for 21 days, followed by a 7-day gap`, [`on day 14 of the cycle for one day`, `after 72 hours of coitus, once`, `on the last day of menstruation, for 7 days`], `Pills are taken daily for 21 days starting within 5 days of the period. After a 7-day break, during which menstruation occurs, the course is repeated.`);
mc(2, 'contraception', `Oral contraceptive pills prevent pregnancy mainly by`, `inhibiting ovulation and implantation and changing the cervical mucus so sperm cannot enter`, [`killing sperm in the epididymis`, `blocking the fallopian tubes`, `stopping sperm production in the testes`], `The hormones in pills have three effects: no ovulation, poor implantation and a changed cervix. They are taken by females, so the testes and epididymis are not involved.`);
mc(2, 'contraception', `Saheli was developed by`, `the Central Drug Research Institute (CDRI), Lucknow`, [`the Indian Agricultural Research Institute, Delhi`, `the National Institute of Virology, Pune`, `the Indian Institute of Science, Bengaluru`], `Saheli is non-steroidal, has few side effects and a good contraceptive value.`);
mc(2, 'contraception', `Injectables and implants as contraceptives are given`, `under the skin, using progestogens alone or with oestrogen`, [`into the uterus, using copper`, `only to males, using testosterone`, `only after pregnancy is confirmed`], `They act like the pills: they stop ovulation and implantation and alter the cervical mucus. They are used for longer periods than daily pills.`);
mc(2, 'contraception', `Emergency contraceptives can prevent pregnancy if used`, `within 72 hours of coitus`, [`within 7 days of coitus`, `only before coitus`, `after the first missed period`], `NCERT says progestogens, progestogen-oestrogen combinations or IUDs can be used within 72 hours of coitus. They are for rare cases such as rape or failure of a method, not for regular use.`);
mc(2, 'MTP', `MTP is NOT needed for which of the following?`, `Choosing the sex of the baby`, [`Unwanted pregnancy from rape`, `Failure of a contraceptive`, `Pregnancy that would harm the health of the mother`], `MTP is legal for unwanted pregnancy due to casual unprotected sex, contraceptive failure or rape, and where continuing is harmful to mother or foetus. It is never allowed for sex selection.`);
mc(2, 'MTP', `Why are MTPs in the second trimester not so safe?`, `They are much riskier and need great care`, [`The foetus is too small to be removed`, `Contraceptives work only then`, `They are banned in the first trimester`], `The risk rises as pregnancy advances. The law and doctors restrict them after 12 weeks.`);
mc(2, 'STI', `Among these STIs, which are NOT completely curable even if detected early?`, `Hepatitis-B, genital herpes and HIV infection`, [`Gonorrhoea, syphilis and chlamydiasis`, `Trichomoniasis and genital warts`, `Syphilis and genital warts`], `NCERT states that barring hepatitis-B, genital herpes and HIV, other STIs are completely curable if detected early and treated properly.`);
mc(2, 'STI', `Which of the following is NOT a way of preventing STIs?`, `Taking antibiotics regularly after each intercourse`, [`Avoiding sex with unknown partners or multiple partners`, `Always using condoms during coitus`, `Consulting a qualified doctor for any doubtful symptom`], `Prevention means avoiding risky contact, using condoms and early checks. Antibiotics do not prevent viral STIs and should not be self-used.`);
mc(2, 'STI', `Apart from sexual contact, STIs such as hepatitis-B and HIV can spread through`, `sharing of needles, blood transfusion and from an infected mother to her foetus`, [`mosquito bites and drinking water`, `handshakes and sharing a plate`, `air and sneezing`], `These viruses pass by blood and body fluids. They do not spread by casual touch, air or food.`);
mc(2, 'infertility', `Infertility is defined as`, `inability to conceive or produce children even after unprotected sexual cohabitation`, [`failure to have a male child`, `loss of the ability to have sex`, `ability to have only one child`], `The causes may be physical, congenital, diseases, drugs, immunological or psychological, in either partner.`);
mc(2, 'ART', `In GIFT, the transfer is of`, `ova collected from a donor into the fallopian tube of another female`, [`zygote into the uterus`, `semen into the vagina`, `an embryo of 16 cells into the fallopian tube`], `GIFT is gamete intra-fallopian transfer. It helps a female who cannot produce ova but can provide a suitable environment for fertilisation and development.`);
mc(2, 'ART', `In ZIFT, the zygote or early embryo with up to 8 blastomeres is transferred into`, `the fallopian tube`, [`the uterus`, `the vagina`, `the ovary`], `ZIFT is zygote intra-fallopian transfer. Embryos with more than 8 blastomeres go into the uterus (IUT).`);
mc(2, 'ART', `An embryo with more than 8 blastomeres is transferred into`, `the uterus (IUT)`, [`the fallopian tube (ZIFT)`, `the vagina (AI)`, `the ovary (GIFT)`], `The 8-blastomere limit is the rule: up to 8 into the fallopian tube, more than 8 into the uterus.`);
mc(2, 'ART', `Artificial insemination (AI) means`, `semen from the husband or a donor is introduced artificially into the vagina or uterus`, [`an embryo is grown outside the body for 9 months`, `ovum is injected with sperm`, `ovum is collected from donor`], `When the semen is put into the uterus it is called intra-uterine insemination (IUI). It is useful when the male cannot inseminate normally or has low sperm count.`);
mc(2, 'amniocentesis', `Which of the following can be detected by amniocentesis?`, `Down syndrome, haemophilia and sickle-cell anaemia`, [`Typhoid, malaria and dengue`, `Cataract, glaucoma and myopia`, `Anaemia, jaundice and diabetes`], `Chromosomal and gene disorders can be found from the foetal cells in the amniotic fluid.`);
mc(2, 'population', `Which measure does NOT help to control population growth?`, `Giving incentives for large families`, [`Raising the marriageable age`, `Educating couples about the small family norm`, `Providing contraceptives easily`], `The small family norm is promoted by incentives to couples with few children. Rewarding larger families would do the opposite.`);
mc(2, 'population', `World population reached about 6 billion in the year`, `2000`, [`1900`, `1950`, `2020`], `NCERT says the population was about 2 billion in 1900 and rose to about 6 billion in 2000. India crossed 1 billion in the year 2000.`);
mc(2, 'population', `India's population at the time of independence (1947) was about`, `350 million`, [`1 billion`, `200 million`, `700 million`], `It was about 350 million in 1947 and reached about 1 billion by 2000.`);
mc(2, 'reproductive health', `Which of the following is a part of the RCH programme?`, `Creating awareness about reproduction, safe sex practices and care of mother and child`, [`Giving only vaccines for polio`, `Taxes on large families`, `Compulsory sterilisation of all citizens`], `RCH covers awareness, sex education, birth control, prenatal and postnatal care, STI prevention and detection of genetic disorders. Nothing in it is compulsory.`);
mc(2, 'reproductive health', `Which of the following helps to build a reproductively healthy society?`, `Sex education in schools`, [`Keeping adolescents unaware of reproductive organs`, `Allowing amniocentesis for sex selection`, `Marriage at an early age`], `Correct information about adolescence, safe sex and STIs removes myths. The other options harm reproductive health.`);
mc(2, 'contraception', `Condoms available in the Indian market under a government name are called`, `Nirodh`, [`Saheli`, `Lippes`, `Progestasert`], `Nirodh is the condom brand of the Government of India. Saheli is the weekly pill.`);
mc(2, 'contraception', `Which pair is correctly matched?`, `Vasectomy and male sterilisation`, [`Tubectomy and male sterilisation`, `Saheli and daily pill of 21 days`, `Lippes loop and copper-releasing IUD`], `Vasectomy is the male method; tubectomy is female. Saheli is weekly and Lippes loop is non-medicated.`);
mc(2, 'surgical', `A common feature of vasectomy and tubectomy is that they`, `block the transport of gametes and are called terminal methods`, [`stop the production of gametes`, `are easily reversible`, `change the level of hormones greatly`], `Sterilisation blocks the passage of sperm or ovum, so fertilisation cannot occur. Hormones and gamete production continue. Reversal is poor.`);

// ---------------------------------------------------------------- Level 3
mc(3, 'contraception', `Which of the following IUDs works partly by making the uterus unsuitable for implantation and the cervix hostile to sperm?`, `Progestasert`, [`Lippes loop`, `Cu7`, `Multiload 375`], `Hormone-releasing IUDs such as Progestasert and LNG-20 give this double effect. Cu-releasing IUDs mainly harm sperm motility and fertilising ability. Lippes loop is non-medicated.`, `Students remember "all IUDs work by stopping implantation". NCERT groups the effects by type of IUD.`);
mc(3, 'contraception', `A woman with a regular 28-day cycle follows periodic abstinence. On which days is intercourse best avoided?`, `Days 10 to 17`, [`Days 1 to 7`, `Days 18 to 28`, `Days 24 to 28 only`], `Ovulation is about the 14th day. The days around it (10-17) are the fertile period. Days before and after are treated as safe, though this method is not very reliable.`);
mc(3, 'STI', `Find the odd one out.`, `Filariasis`, [`Genital warts`, `Chlamydiasis`, `Trichomoniasis`], `Genital warts, chlamydiasis and trichomoniasis are STIs. Filariasis is a mosquito-borne disease.`);
mc(3, 'ART', `Which technique would be suitable for a female who cannot produce ova but can provide a suitable environment for fertilisation and development?`, `GIFT with ova from a donor`, [`Vasectomy`, `Copper-T insertion`, `Amniocentesis`], `In GIFT the ovum of a donor is placed in the fallopian tube of this woman. Fertilisation then occurs inside her body and she carries the pregnancy.`);
mc(3, 'ART', `A couple's problem is that the husband's sperm cannot penetrate the ovum. Which ART is best?`, `ICSI`, [`GIFT`, `IUI`, `Tubectomy`], `ICSI puts one sperm directly into the cytoplasm of the ovum, so penetration is no longer needed. GIFT and IUI both depend on the sperm reaching and entering the ovum naturally.`);
mc(3, 'ART', `In IVF, the earliest stage at which the embryo can be transferred to the uterus is when it has`, `more than 8 blastomeres`, [`2 blastomeres`, `only the zygote stage`, `exactly 8 blastomeres`], `Zygote or an embryo with up to 8 blastomeres goes into the fallopian tube (ZIFT). Only an embryo with more than 8 blastomeres goes to the uterus (IUT).`, `"Up to 8" includes 8, so exactly 8 goes to the fallopian tube.`);
mc(3, 'ART', `Which of the following is a correct pair?`, `AI : semen is put into the vagina or uterus`, [`ICSI : ovum is put into the fallopian tube`, `GIFT : zygote is put into the uterus`, `IUT : zygote is put into the fallopian tube`], `AI places semen artificially in the female tract. ICSI injects a sperm into the ovum. GIFT moves gametes (not zygotes) into the tube. IUT moves embryos of more than 8 blastomeres to the uterus.`);
mc(3, 'surgical', `After a tubectomy, a woman will`, `continue to ovulate and menstruate normally`, [`stop menstruating`, `stop producing oestrogen`, `not be able to have sex`], `Only the fallopian tubes are cut and tied. The ovaries and uterus work as before, so hormones, ovulation and periods continue. The ovum just cannot meet sperm.`);
mc(3, 'surgical', `After a vasectomy, a man`, `continues to have normal sexual drive and testosterone, but his semen has no sperm`, [`loses sexual desire`, `cannot ejaculate`, `stops producing testosterone`], `Sperm cannot pass beyond the cut vas deferens. Seminal fluid from the seminal vesicles and prostate is still added, so ejaculation occurs. The testes still secrete testosterone.`);
mc(3, 'contraception', `Which method is least reliable?`, `Periodic abstinence`, [`Hormone-releasing IUD`, `Tubectomy`, `Combined oral pill`], `Fertile days can shift, so periodic abstinence and coitus interruptus have high failure rates. Hormones, IUDs and surgery are much more effective.`);
mc(3, 'contraception', `Which of the following contraceptives is used ONLY by females?`, `Diaphragm`, [`Condom`, `Vasectomy`, `Coitus interruptus`], `Diaphragms, cervical caps and vaults are for the female. Condoms exist for both, vasectomy is male, and withdrawal is a male action.`);
mc(3, 'contraception', `A newly delivered mother is breast-feeding her baby fully and has not had periods. She is protected from pregnancy by`, `lactational amenorrhea, only for about six months`, [`lactational amenorrhea, for as long as she feeds`, `a natural IUD effect`, `periodic abstinence`], `Hormones of lactation suppress ovulation. The effect is dependable only for about six months after delivery with full feeding, so the chance of pregnancy is very low in that period only.`);
mc(3, 'contraception', `Why do combined oral pills not give protection against HIV?`, `They do not form a barrier between partners`, [`They kill only sperm but not viruses`, `They are meant for males`, `They contain steroids that are broken down by HIV`], `Pills work on the female hormones. Only barriers like condoms stop body fluids from passing between partners.`);
mc(3, 'contraception', `Which of the following is true about oral contraceptive pills?`, `They contain progestogen or progestogen-oestrogen combinations`, [`They contain only testosterone`, `They contain copper salts`, `They are taken only after coitus`], `Pills contain female hormones (progestogens alone or with oestrogens) and are taken daily on a schedule.`);
mc(3, 'MTP', `MTP is legal in India for`, `unwanted pregnancy caused by contraceptive failure, rape or casual sex, and where continuing may harm mother or foetus`, [`any pregnancy at any stage on request`, `the choice of male baby`, `pregnancy up to the 9th month`], `The Act of 1971 allows MTP with strict conditions to avoid misuse. It is not for sex selection.`);
mc(3, 'STI', `Which of the following can spread from an infected mother to her foetus?`, `HIV and hepatitis-B`, [`Only gonorrhoea`, `None of the STIs`, `Only syphilis and cholera`], `NCERT lists blood transfusion, shared needles and infected mother to foetus as routes for hepatitis-B and HIV.`);
mc(3, 'STI', `Early symptoms of STIs are often`, `minor, such as itching, fluid discharge, slight pain and swellings in the genital region, so they are ignored`, [`severe fever and paralysis`, `loss of vision`, `an immediate death`], `Because the symptoms are mild, people may hide them or neglect them. This leads to complications such as pelvic inflammatory diseases, abortions, stillbirths, ectopic pregnancies and infertility.`);
mc(3, 'STI', `Which of the following is a possible complication of untreated STIs in a female?`, `Pelvic inflammatory disease and infertility`, [`Early menarche`, `Increased milk production`, `Increased fertility`], `NCERT lists pelvic inflammatory diseases (PID), abortions, stillbirths, ectopic pregnancies and infertility, besides cancer of the reproductive tract.`);
mc(3, 'amniocentesis', `The sample used in amniocentesis is`, `amniotic fluid containing cells of the foetus`, [`blood from the mother's arm`, `a piece of the placenta only`, `urine of the foetus`], `The fluid surrounding the foetus holds shed foetal cells. They are cultured and the chromosomes are examined.`);
mc(3, 'population', `Which of the following is a goal of reproductive health programmes?`, `Better detection and diagnosis of genetic disorders and prenatal care`, [`Increasing the number of births per year`, `Removing all STI information from schools`, `Promoting sex determination tests`], `The RCH programme includes detection of genetic disorders, STI control, birth control, pre-natal and post-natal care and awareness, with a ban on sex-determination tests.`);
mc(3, 'population', `Which of the following helps in reducing the population growth rate most directly?`, `Fall in the birth rate through use of contraceptives`, [`Fall in the death rate`, `Fall in the infant mortality rate`, `Rise in life expectancy`], `Falling death rates raise population growth. Birth control reduces the number of births.`, `Lower IMR and MMR are good health outcomes but they make population grow faster.`);
mc(3, 'ART', `In vivo fertilisation is a feature of`, `GIFT`, [`IVF`, `ZIFT`, `ICSI`], `In GIFT gametes are placed in the fallopian tube and fertilisation takes place inside the body. IVF, ZIFT and ICSI all unite the gametes outside the body (in vitro) first.`, `GIFT is an ART, so many think it is in vitro. Only the gametes, not a zygote, are transferred.`);
mc(3, 'ART', `Which of the following does NOT need the collection of an ovum?`, `Intra-uterine insemination (IUI)`, [`IVF`, `ICSI`, `GIFT`], `In IUI semen is introduced into the uterus and fertilisation happens in the body. IVF, ICSI and GIFT all use ova collected from a donor or the wife.`);
mc(3, 'contraception', `Which of the following needs insertion by a doctor or a trained nurse?`, `Intra-uterine device`, [`Condom`, `Oral pill`, `Periodic abstinence`], `IUDs are inserted through the vagina into the uterus by an expert. Condoms are self-inserted and pills are swallowed.`);
mc(3, 'infertility', `Which of the following is NOT a possible cause of infertility?`, `Use of a condom in the past`, [`Immunological reasons`, `Psychological reasons`, `Congenital defects`], `NCERT lists physical, congenital, diseases, drugs, immunological and psychological causes. Using a condom earlier does not cause infertility.`);
mc(3, 'infertility', `When ART methods also fail, a couple who want a child may`, `adopt a child`, [`undergo vasectomy`, `use emergency contraceptives`, `take MTP`], `Adoption is the alternative for couples who cannot have children through ART.`);

asr(3, 'contraception', `Condoms give protection from many sexually transmitted infections.`, `A condom is a barrier that stops semen and body fluids from passing between the partners.`, 0, `Condoms cover the penis (or the vagina and cervix) and keep infected fluids and mucosal contact apart. R explains A.`);
asr(3, 'contraception', `Lactational amenorrhea is not a dependable method of birth control after six months of delivery.`, `After six months, feeding is usually less intense and ovulation may restart.`, 0, `The method works because intense lactation suppresses ovulation. When feeding drops after about six months, ovulation can return even before periods, so R explains A.`);
asr(3, 'contraception', `Saheli contains steroidal hormones like the combined pill.`, `Saheli is taken once a week.`, 3, `Saheli is a non-steroidal pill, so A is false. R is true: it is a once-a-week pill.`, `The weekly schedule is true, which tempts you to accept A.`);
asr(3, 'surgical', `A man who has undergone vasectomy usually shows no change in sexual drive.`, `Vasectomy blocks only the vas deferens, and the testes continue to secrete testosterone.`, 0, `Sexual desire depends on testosterone from the Leydig cells of the testes, which are untouched. R explains A.`);
asr(3, 'MTP', `MTP is much riskier in the second trimester than in the first.`, `Risk to the mother grows as the pregnancy advances.`, 0, `NCERT says MTPs are safe up to 12 weeks and much riskier afterwards. R states the reason in general terms and explains A.`);
asr(3, 'ART', `A zygote with 16 blastomeres cannot be transferred into the fallopian tube in ZIFT.`, `ZIFT is for a zygote or an embryo with up to 8 blastomeres.`, 0, `The upper limit in ZIFT is 8 blastomeres. A larger embryo is transferred into the uterus (IUT). R directly explains A.`);
asr(3, 'amniocentesis', `Amniocentesis is completely banned in India.`, `Amniocentesis can reveal genetic disorders in the foetus.`, 3, `The statutory ban is on its use for sex determination only. It remains allowed to detect genetic and chromosomal disorders. So A is false and R is true.`, `Many remember "banned" and forget "for sex determination only".`);
asr(3, 'contraception', `Emergency contraceptives are not meant for routine use.`, `They are advised only for rare occasions such as rape or failure of a regular method.`, 0, `They should be used within 72 hours of coitus in unusual situations. R is the reason for A.`);
asr(3, 'population', `A fall in infant mortality rate contributes to population explosion.`, `More children survive to reproductive age and have children of their own.`, 0, `With birth rate unchanged and death rate lower, the population grows quickly. R explains A.`);
asr(3, 'contraception', `Oral contraceptive pills are used only by females.`, `The hormones in these pills inhibit ovulation and alter the cervical mucus.`, 0, `Ovulation and cervical mucus belong to the female. The hormones in the pills act on them, so only females use these pills.`);

stm(3, 'contraception', `Copper-T releases hormones to prevent pregnancy.`, `LNG-20 is a hormone-releasing IUD.`, 3, `Copper-T releases copper ions, not hormones, so Statement I is incorrect. LNG-20 releases levonorgestrel, so Statement II is correct.`);
stm(3, 'surgical', `Tubectomy is a surgical sterilisation method for females.`, `In tubectomy the vas deferens is cut and tied.`, 2, `Tubectomy cuts and ties the fallopian tubes. Cutting the vas deferens is vasectomy. So Statement I is correct and II is incorrect.`);
stm(3, 'contraception', `Condoms can be used by both males and females.`, `Condoms are reusable after washing.`, 2, `Male condoms cover the penis and female condoms cover the vagina and cervix. They are disposable, so Statement II is incorrect.`);
stm(3, 'ART', `GIFT is the transfer of gametes into the fallopian tube.`, `ZIFT is the transfer of a zygote into the fallopian tube.`, 0, `Both statements describe the definitions given by NCERT.`);
stm(3, 'STI', `STIs are also called reproductive tract infections (RTIs).`, `All STIs are completely curable if detected early.`, 2, `STIs are venereal diseases or RTIs. But hepatitis-B, genital herpes and HIV infection are not completely curable, so Statement II is incorrect.`);
stm(3, 'contraception', `Saheli is a steroidal pill.`, `Saheli is taken daily for 21 days.`, 1, `Saheli is non-steroidal and once a week. Both statements are incorrect.`);
stm(3, 'contraception', `Implants are placed under the skin.`, `Injectables and implants can stop ovulation and implantation, as the pills do.`, 0, `Both statements agree with NCERT. They carry progestogens or progestogen-oestrogen combinations.`);
stm(3, 'ART', `ICSI is a procedure in which a sperm is injected directly into the ovum.`, `The embryo formed by ICSI is allowed to develop in the laboratory until birth.`, 2, `After ICSI the zygote or embryo is transferred into the fallopian tube or the uterus, where the pregnancy continues. It cannot grow to birth in the lab.`);
stm(3, 'contraception', `Copper ions released by Cu-T stop ovulation.`, `Cu ions suppress sperm motility and the fertilising capacity of sperm.`, 3, `Cu-T does not act on ovulation. It makes the uterine environment harmful to sperm, so Statement I is incorrect and II is correct.`);
stm(3, 'population', `Raising the marriageable age of females to 18 helps to reduce the birth rate.`, `A small family norm is promoted by giving incentives to couples with fewer children.`, 0, `Both are population-control measures that NCERT mentions.`);

match(3, 'contraception', 'rh-m1', 'Contraceptives and their features', [`A. Lippes loop`, `B. Saheli`, `C. Vasectomy`, `D. Condom`], [`p. Once-a-week non-steroidal pill`, `q. Non-medicated IUD`, `r. Cutting and tying of the vas deferens`, `s. Barrier made of thin rubber sheath`], `A-q, B-p, C-r, D-s`, [`A-p, B-q, C-r, D-s`, `A-q, B-p, C-s, D-r`, `A-r, B-p, C-q, D-s`], `Lippes loop is plastic and releases nothing (q). Saheli is the weekly non-steroidal pill (p). Vasectomy is cutting the vas deferens (r). A condom is a rubber sheath barrier (s).`);
match(3, 'ART', 'rh-m2', 'ART techniques and their meaning', [`A. GIFT`, `B. ZIFT`, `C. IUI`, `D. ICSI`], [`p. Sperm injected into ovum`, `q. Donor ovum transferred into fallopian tube`, `r. Semen put into uterus`, `s. Zygote transferred into fallopian tube`], `A-q, B-s, C-r, D-p`, [`A-s, B-q, C-r, D-p`, `A-q, B-s, C-p, D-r`, `A-r, B-s, C-q, D-p`], `GIFT is gamete transfer (q). ZIFT is zygote transfer into the tube (s). IUI is semen into the uterus (r). ICSI is sperm injection into an ovum (p).`);
match(3, 'contraception', 'rh-m3', 'Contraceptive types and examples', [`A. Copper-releasing IUD`, `B. Hormone-releasing IUD`, `C. Barrier method for females`, `D. Terminal (surgical) method`], [`p. LNG-20`, `q. Multiload 375`, `r. Vault`, `s. Tubectomy`], `A-q, B-p, C-r, D-s`, [`A-p, B-q, C-r, D-s`, `A-q, B-p, C-s, D-r`, `A-r, B-q, C-p, D-s`], `Multiload 375 releases copper (q). LNG-20 releases a hormone (p). A vault is a rubber barrier placed in the female tract (r). Tubectomy is surgical sterilisation (s).`);

pass('rh-p1', `A couple with blocked fallopian tubes`, `A couple has been trying to have a child for five years. Tests show that the husband's sperm count and motility are normal. The wife ovulates regularly and her uterus is healthy, but both her fallopian tubes are blocked. The doctor advises assisted reproductive technology.`);
pq('rh-p1', 3, 'ART', `Which technique is most suitable for this couple?`, `IVF followed by transfer of the embryo into the uterus`, [`Tubectomy`, `Artificial insemination into the vagina`, `Vasectomy`], `Because the tubes are blocked, the ovum cannot meet sperm in the body. In IVF the ovum and sperm are united in the laboratory, and an embryo with more than 8 blastomeres can go straight into the uterus (IUT).`);
pq('rh-p1', 3, 'ART', `Why is ZIFT not a good choice here?`, `ZIFT places the zygote into the fallopian tube, which is blocked`, [`ZIFT needs a donor sperm`, `ZIFT works only in males`, `ZIFT is an IUD`], `A zygote placed in a blocked tube cannot move to the uterus. For this wife, the embryo must go into the uterus.`);
pq('rh-p1', 4, 'ART', `Which technique would also fail in this case?`, `GIFT, because the gametes are placed in the blocked fallopian tube`, [`IUT of an embryo into the uterus`, `IVF in the laboratory`, `ICSI in the laboratory`], `GIFT needs a working fallopian tube for fertilisation and passage of the embryo. IVF and ICSI happen outside, and IUT bypasses the tube.`, `Both ZIFT and GIFT use the fallopian tube.`);

pass('rh-p2', `A woman on the combined pill`, `Meena starts a combined oral contraceptive pill on the second day of her period (day 1 = first day of bleeding). She takes one pill daily for 21 days, then stops for 7 days, and restarts the course.`);
pq('rh-p2', 3, 'contraception', `On which day of the cycle count (from day 1) does she take her last pill in the first course?`, `Day 22`, [`Day 21`, `Day 23`, `Day 28`], `She starts on day 2. Twenty-one pills run from day 2 to day 22 (22 - 2 + 1 = 21).`, `Starting on day 2, not day 1, shifts the last day.`);
pq('rh-p2', 3, 'contraception', `What is the purpose of the 7-day gap?`, `Menstruation occurs during the gap`, [`The ovary releases an ovum`, `The cervical mucus becomes thin`, `The IUD is removed`], `When the hormone supply stops, the uterine lining sheds and a period occurs. The course then restarts.`);
pq('rh-p2', 4, 'contraception', `Which action of the pill is NOT correct?`, `It kills sperm in the vagina`, [`It inhibits ovulation`, `It inhibits implantation`, `It alters the quality of cervical mucus to prevent entry of sperm`], `Pills act on ovulation, implantation and the cervical mucus. Killing sperm is the job of spermicides and copper ions.`);

pass('rh-p3', `A clinic and the law`, `A clinic offers to tell expectant parents the sex of the foetus by testing a sample of amniotic fluid taken through the abdominal wall. An inspector notes that the clinic is breaking the law. Another clinic uses the same sampling method to look at the chromosomes of a foetus in a mother who is 41 years old.`);
pq('rh-p3', 3, 'amniocentesis', `Why was the first clinic breaking the law?`, `Sex determination by amniocentesis is a statutory offence in India`, [`Amniotic fluid cannot be sampled`, `Any prenatal test is banned`, `Amniocentesis is allowed only after birth`], `The technique is allowed for detecting genetic and chromosomal disorders but not for finding out the sex of the foetus.`);
pq('rh-p3', 3, 'amniocentesis', `A foetus with an extra chromosome 21 has how many chromosomes in its cells?`, `47`, [`45`, `46`, `48`], `Normal humans have 46. An extra chromosome 21 (Down syndrome, trisomy 21) makes 47.`);
pq('rh-p3', 4, 'amniocentesis', `A long-term social result of misuse of the technique is`, `a skewed sex ratio because of female foeticide`, [`more twins`, `higher birth rate of males only in all countries`, `greater infant mortality of both sexes`], `Sex-selective abortions of female foetuses lower the proportion of females in the population.`);

nat(3, 'contraception', `The fertile period in a 28-day cycle is taken as day 10 to day 17, both included. For how many days should a couple practising periodic abstinence avoid intercourse?`, 8, `Count the days from 10 to 17 inclusive: 17 - 10 + 1 = 8 days.`, 'days', `Forgetting to include both end days gives 7.`);
nat(3, 'contraception', `In a 28-day cycle, with days 10 to 17 considered fertile, how many days are outside the fertile period?`, 20, `Fertile days = 8. The other days = 28 - 8 = 20.`, 'days');
nat(3, 'contraception', `A woman uses a combined pill with 21 pills followed by a 7-day gap. In 4 complete courses, on how many days does she take no pill?`, 28, `Each course has a 7-day gap. Four courses give 4 × 7 = 28 days with no pill.`, 'days');
nat(3, 'contraception', `How many of the following are copper-releasing IUDs: Lippes loop, Cu-T, Cu7, Multiload 375, LNG-20, Progestasert?`, 3, `Copper-releasing are Cu-T, Cu7 and Multiload 375, that is 3. Lippes loop is non-medicated, and LNG-20 and Progestasert are hormone-releasing.`, undefined, `Lippes loop is an IUD but not a copper one.`);
nat(3, 'contraception', `How many of the following are barrier methods: condom, diaphragm, Lippes loop, cervical cap, vault, Saheli, tubectomy?`, 4, `Barriers: condom, diaphragm, cervical cap and vault, that is 4. Lippes loop is an IUD, Saheli is a pill and tubectomy is surgical.`);
nat(3, 'STI', `NCERT names these STIs: gonorrhoea, syphilis, genital herpes, chlamydiasis, genital warts, trichomoniasis, hepatitis-B and HIV infection. How many of them are completely curable if detected early?`, 5, `Hepatitis-B, genital herpes and HIV are not completely curable. So 8 - 3 = 5 are curable.`);
nat(3, 'population', `India's population was about 350 million in 1947 and about 1000 million in 2000. By what factor did it increase? Give the answer to two decimals.`, 2.86, `Factor = 1000 / 350 = 2.857, which is 2.86 to two decimals.`, 'times', undefined, 0.01);
nat(3, 'ART', `A zygote divides by mitosis repeatedly. After how many cleavage divisions will it first have more than 8 blastomeres?`, 4, `After n divisions there are 2^n blastomeres: 2, 4, 8, 16. Three divisions give 8 (still allowed in ZIFT). The first count above 8 is after 4 divisions (16).`, undefined, `8 is not more than 8.`);

// ---------------------------------------------------------------- Level 4
mc(4, 'contraception', `Which of the following is a correct statement about Cu-T and LNG-20?`, `Cu-T releases copper ions that harm sperm; LNG-20 releases a progestogen that makes the uterus unsuitable for implantation`, [`Both release hormones that stop ovulation completely`, `Cu-T releases a progestogen and LNG-20 releases copper`, `Both are non-medicated and act only as a physical barrier`], `The type of ion or hormone decides the action. Cu ions act on sperm. LNG-20 acts mainly on the uterus lining and cervical mucus. Neither is just a physical barrier.`, `Some students link all IUDs with ovulation control, which is the pill's job.`);
mc(4, 'contraception', `Combined oral pills prevent ovulation mainly because their hormones`, `feed back on the pituitary and hypothalamus and stop the mid-cycle surge of LH and FSH`, [`directly kill the ovum`, `block the fallopian tube`, `stop the corpus luteum from forming after ovulation`], `Steady oestrogen and progestogen from outside suppress the pituitary, so there is no LH surge. Without the LH surge there is no ovulation, as learnt in the menstrual cycle chapter.`, `The corpus luteum forms only after ovulation, so it cannot be the cause.`, 'single');
mc(4, 'contraception', `A woman used a copper IUD within 72 hours of unprotected intercourse. This is possible because`, `IUDs can be used as emergency contraceptives and prevent fertilisation or implantation`, [`IUDs make sperm travel faster`, `IUDs remove the ovum`, `IUDs act only after 7 days`], `NCERT lists IUDs, along with progestogen-based pills, as emergency contraception within 72 hours. Cu ions harm sperm and the uterus lining becomes hostile.`);
mc(4, 'surgical', `After vasectomy, which process continues in the male?`, `Spermatogenesis in the seminiferous tubules and secretion of testosterone`, [`Passage of sperm into semen`, `Flow of sperm through the vas deferens`, `Sperm storage in the semen`], `Only the vas deferens is blocked. Sperm are still made in the testis. They simply cannot reach the semen.`, `Students assume that vasectomy stops sperm production.`);
mc(4, 'ART', `Which statement about a "test-tube baby" is INCORRECT?`, `The baby grows for nine months in a test tube`, [`Fertilisation is carried out outside the body`, `The early embryo is transferred into the female tract`, `The development after transfer takes place in the mother's body`], `Only fertilisation and the first few cleavages occur in the laboratory. The foetus develops in the uterus.`, `The word "test tube" misleads.`);
mc(4, 'ART', `Which pair of techniques both involve fertilisation outside the body?`, `IVF and ICSI`, [`GIFT and IUI`, `IUI and AI`, `GIFT and ZIFT`], `IVF and ICSI form the zygote in the laboratory. GIFT places gametes inside the tube, and AI or IUI introduces semen into the female tract. ZIFT starts with a zygote made in vitro but GIFT does not.`);
mc(4, 'ART', `Which of the following correctly states the difference between IUI and IUT?`, `IUI puts semen into the uterus; IUT puts an embryo of more than 8 blastomeres into the uterus`, [`IUI puts an embryo into the uterus; IUT puts semen into the uterus`, `IUI is fertilisation outside the body; IUT is fertilisation inside`, `IUI and IUT are the same`], `IUI is a way of artificial insemination (semen). IUT is a part of IVF (embryo transfer).`, `The two abbreviations look similar.`);
mc(4, 'contraception', `Which statement about lactational amenorrhea is NOT correct?`, `It is reliable for as long as the baby is breast-fed, even after one year`, [`It works because ovulation does not occur during intense lactation`, `Periods do not return during this time`, `It is effective only up to about six months after delivery`], `NCERT limits the method to about six months after delivery and says the chances of conception are almost nil only during intense lactation.`);
mc(4, 'contraception', `A couple relies on withdrawal. A common reason for its failure is that`, `a small amount of semen or pre-ejaculatory fluid may already have entered the vagina`, [`the ovum is released only after ejaculation`, `the sperm die outside the body quickly`, `the ovum is released from the male`], `Because withdrawal can be late or incomplete, sperm may already be in the vagina. The method is not dependable.`);
mc(4, 'STI', `Which group has all STIs caused by viruses?`, `Genital herpes, genital warts, hepatitis-B`, [`Gonorrhoea, syphilis, chlamydiasis`, `Trichomoniasis, genital warts, gonorrhoea`, `Syphilis, hepatitis-B, trichomoniasis`], `Herpes (HSV), genital warts (HPV) and hepatitis-B (HBV) are viral. Gonorrhoea, syphilis and chlamydiasis are bacterial. Trichomoniasis is protozoan. (The causative organisms are beyond the NCERT text, but they are standard facts.)`);
mc(4, 'STI', `Syphilis is caused by`, `Treponema pallidum, a bacterium`, [`Neisseria gonorrhoeae`, `Trichomonas vaginalis`, `Human papillomavirus`], `Syphilis is bacterial. Gonorrhoea is by <i>Neisseria gonorrhoeae</i>, trichomoniasis by the protozoan <i>Trichomonas vaginalis</i>, and genital warts by HPV.`, `Beyond NCERT's own text, but a standard supporting fact.`);
mc(4, 'STI', `Which pair is INCORRECT?`, `Trichomoniasis : bacterium`, [`Gonorrhoea : bacterium`, `Genital warts : virus`, `Chlamydiasis : bacterium`], `Trichomoniasis is caused by the protozoan <i>Trichomonas vaginalis</i>. Chlamydiasis (<i>Chlamydia trachomatis</i>) and gonorrhoea are bacterial; warts are viral.`);
mc(4, 'STI', `Why are STI symptoms often neglected, leading to serious complications?`, `They are mild at first, and there is a social stigma attached to them`, [`They always show up after many years`, `They are not dangerous`, `They disappear without treatment`], `Mild symptoms and social taboos make people hide the problem. Late treatment leads to PID, ectopic pregnancy, infertility and spread to others.`);
mc(4, 'amniocentesis', `A pregnant woman aged 42 has an amniocentesis; the foetal cells show 47 chromosomes including an extra X (XXY). The foetus has`, `Klinefelter syndrome`, [`Turner syndrome`, `Down syndrome`, `Edwards syndrome`], `XXY is Klinefelter syndrome (male, 47 chromosomes). Turner is 45, XO. Down is trisomy 21 (47 with XX or XY plus an extra 21).`, `All three have 45 or 47, so you must read the sex chromosomes.`);
mc(4, 'population', `Which of the following sets of programmes is correctly matched to a goal of reproductive health?`, `Pre-natal and post-natal care : reducing maternal and infant mortality`, [`Sex education : increasing STIs`, `Amniocentesis for sex determination : ensuring a balanced sex ratio`, `Promotion of unprotected sex : controlling population`], `Better care before and after birth saves mothers and babies. The other pairs are opposite to the real purpose.`);
mc(4, 'reproductive health', `Which of the following is a result of the RCH programme's emphasis on pre-natal diagnosis, but also a major social concern?`, `Misuse of foetal sex determination leading to female foeticide`, [`Increase in the male infertility`, `Reduced milk secretion`, `Increase in the number of triplets`], `Diagnostic tools can be misused to find the sex of the foetus, which is why the law bans the sex test.`);
mc(4, 'contraception', `Which is NOT a way by which hormonal contraceptives prevent pregnancy?`, `They stop sperm production in the female`, [`Inhibit ovulation`, `Inhibit implantation`, `Alter the cervical mucus`], `Females do not make sperm. Hormonal pills, injectables and implants act on ovulation, implantation and cervical mucus.`);
mc(4, 'contraception', `Which method is correctly described as "reversible and acting for a long period without needing daily attention"?`, `Hormone-releasing IUD`, [`Combined oral pill`, `Condom`, `Withdrawal`], `IUDs sit in the uterus for years and can be removed to restore fertility. Pills and condoms need regular action, and withdrawal needs control every time.`);
mc(4, 'ART', `A woman whose ova are normal but whose husband produces no sperm should preferably use`, `artificial insemination with semen from a donor`, [`GIFT`, `Tubectomy`, `Vasectomy`], `AI with donor semen solves the sperm problem and fertilisation can occur in the female tract. GIFT is for transfer of an ovum from a donor female. Tubectomy and vasectomy are contraception.`);
mc(4, 'contraception', `Which of the following contraceptive pairs is the best to avoid both pregnancy and many STIs at the same time?`, `Condom, used consistently`, [`Copper-T alone`, `Combined pill alone`, `Lactational amenorrhea`], `Only barriers prevent pregnancy and also block infection. Other options do not stop the exchange of body fluids.`);
mc(4, 'surgical', `Sterilisation methods are called terminal methods because they`, `permanently block the passage of gametes`, [`stop the secretion of sex hormones`, `have to be repeated every month`, `are used only at the end of the reproductive life`], `The gametes cannot be transported, so conception cannot occur. They are not easy to reverse.`);
mc(4, 'ART', `Which of the following will be needed in all of these: IVF, ICSI, ZIFT and IUT?`, `Fertilisation in the laboratory and a later embryo transfer`, [`Donor ovum only`, `Surgical removal of the uterus`, `Fertilisation inside the uterus`], `All four start with a zygote or embryo made outside the body, which is then transferred to the female tract.`);
mc(4, 'infertility', `Which of the following is an immunological cause of infertility?`, `Antibodies against sperm in the female or male`, [`Blocked fallopian tubes by birth`, `Stress of the couple`, `Use of drugs`], `Immune responses against the gametes can lower fertility. Blocked tubes are physical or congenital, stress is psychological, and drugs are a separate cause.`);

asr(4, 'contraception', `Hormone-releasing IUDs are better at preventing pregnancy than non-medicated IUDs.`, `Hormone-releasing IUDs make the uterus unsuitable for implantation and the cervix hostile to sperm.`, 0, `Non-medicated IUDs act mainly as a foreign body. Hormone-releasing ones add the double effect on the uterus and the cervical mucus. So R explains A.`);
asr(4, 'ART', `GIFT is described as an in vivo fertilisation method, unlike IVF.`, `In GIFT the gametes are transferred into the fallopian tube, where fertilisation takes place.`, 0, `The ovum and sperm meet in the tube inside the female body, so fertilisation is in vivo. R is the explanation of A.`);
asr(4, 'STI', `Hepatitis-B can be transmitted by blood transfusion.`, `Hepatitis-B and HIV can be completely cured if detected early.`, 2, `Blood transfusion is a known route for hepatitis-B, so A is true. NCERT says hepatitis-B, genital herpes and HIV are not completely curable, so R is false.`);
asr(4, 'surgical', `Vasectomy and tubectomy are not suitable for couples who may want children in future.`, `Sterilisation methods are difficult to reverse.`, 0, `Because the gamete passage is cut and tied, restoring fertility is hard. R explains A.`);
asr(4, 'contraception', `A male condom cannot be called a hormonal contraceptive.`, `A male condom is a mechanical barrier made of thin rubber or latex sheath.`, 0, `It stops semen from entering the female tract and has no hormone. R explains A.`);
asr(4, 'ART', `ICSI can help a male with very few or weak sperm.`, `Only one sperm is needed because it is injected directly into the ovum.`, 0, `The sperm does not have to swim or penetrate the egg coat, so a single viable sperm is enough. R explains A.`);
asr(4, 'population', `Increasing the proportion of people in the reproductive age group adds to population growth.`, `Fertility of the females decreases greatly after menopause.`, 1, `More people of reproductive age means more births, so A is true. R is also true (menopause ends fertility) but it does not explain why the reproductive age group boosts growth.`, `The A-R link is only loosely connected.`);
asr(4, 'contraception', `Emergency contraceptives can be used regularly instead of other contraceptives.`, `They are taken within 72 hours of coitus.`, 3, `A is false: they are for emergencies such as rape or a failed method, not for regular use. R is true.`);

stm(4, 'contraception', `Saheli is taken weekly and is non-steroidal.`, `The combined oral pill is taken for 21 days, with a 7-day break.`, 0, `Both statements are as NCERT describes.`);
stm(4, 'ART', `In IUT, embryos of more than 8 blastomeres are transferred into the uterus.`, `In ZIFT, zygotes are transferred into the uterus.`, 2, `ZIFT places a zygote or embryo of up to 8 blastomeres into the fallopian tube, not the uterus. Statement II is incorrect.`);
stm(4, 'STI', `Gonorrhoea is curable if detected early and treated.`, `Genital herpes is curable if detected early and treated.`, 2, `Genital herpes is among the STIs that are not completely curable. Statement II is incorrect.`);
stm(4, 'surgical', `In tubectomy, the incision may be made in the abdomen or through the vagina.`, `In vasectomy, a small incision is made in the scrotum.`, 0, `Both match the descriptions of the surgical methods.`);
stm(4, 'contraception', `All IUDs release copper ions.`, `Cu-T is used for delaying or spacing of pregnancies.`, 3, `Only Cu-releasing IUDs do; Lippes loop is non-medicated and others release hormones. Statement I is incorrect; Statement II is correct.`);
stm(4, 'MTP', `MTP is safe throughout pregnancy.`, `MTP was legalised in India in 1951.`, 1, `MTP is safest in the first 12 weeks, and was legalised in 1971. Both are wrong.`);
stm(4, 'population', `Raising the age of marriage and educating couples help to control the population.`, `Rapid fall in death rate has no effect on population growth.`, 2, `Statement I is correct. A fall in death rate raises growth, so Statement II is incorrect.`);

match(4, 'STI', 'rh-m4', 'STIs and their causative organisms (beyond NCERT text)', [`A. Syphilis`, `B. Gonorrhoea`, `C. Trichomoniasis`, `D. Genital warts`], [`p. Neisseria gonorrhoeae`, `q. Treponema pallidum`, `r. Trichomonas vaginalis`, `s. Human papillomavirus`], `A-q, B-p, C-r, D-s`, [`A-p, B-q, C-r, D-s`, `A-q, B-p, C-s, D-r`, `A-r, B-q, C-p, D-s`], `Syphilis: <i>Treponema pallidum</i> (q). Gonorrhoea: <i>Neisseria gonorrhoeae</i> (p). Trichomoniasis: <i>Trichomonas vaginalis</i>, a protozoan (r). Warts: HPV (s).`, `NCERT lists the diseases but does not always name the organisms; they are standard supporting facts.`);
match(4, 'contraception', 'rh-m5', 'Numbers in reproductive health', [`A. MTP is relatively safe up to`, `B. Emergency contraceptive window`, `C. Lactational amenorrhea gives protection for`, `D. Gap in each combined pill course`], [`p. 72 hours`, `q. 12 weeks`, `r. 7 days`, `s. 6 months`], `A-q, B-p, C-s, D-r`, [`A-p, B-q, C-s, D-r`, `A-q, B-p, C-r, D-s`, `A-s, B-p, C-q, D-r`], `MTP: 12 weeks (q). Emergency contraception: 72 hours (p). Lactational amenorrhea: six months (s). The pill gap is 7 days (r).`);

nat(4, 'contraception', `A combined pill course is 21 days of pills followed by a 7-day gap, repeated without any break. How many complete courses fit into one year of 365 days?`, 13, `One course is 28 days. 365 / 28 = 13.04, so 13 complete courses fit.`, undefined, `Rounding up to 14 wrongly counts an incomplete course.`);
nat(4, 'ART', `Among IVF, ZIFT, GIFT, ICSI, IUT, AI and IUI, how many involve fertilisation outside the body before the transfer?`, 4, `IVF, ZIFT, ICSI and IUT start with an in vitro zygote or embryo (4). GIFT places gametes in the tube, and AI and IUI introduce semen into the female tract, so fertilisation is in vivo.`, undefined, `ZIFT and IUT are transfer steps that follow in vitro fertilisation, so they count.`);
nat(4, 'STI', `Of these seven: syphilis, gonorrhoea, chlamydiasis, genital herpes, hepatitis-B, trichomoniasis and genital warts, how many are caused by viruses?`, 3, `Viral: genital herpes, hepatitis-B and genital warts (3). Syphilis, gonorrhoea and chlamydiasis are bacterial; trichomoniasis is protozoan.`);
nat(4, 'population', `A population is 6 billion in year 2000 and 2 billion in 1900. By what factor did it multiply in 100 years?`, 3, `6 / 2 = 3.`, 'times');

// ---------------------------------------------------------------- Level 5
mc(5, 'ART', `Which of the following techniques involve introducing ONLY semen and not any ovum or embryo into the female?`, `AI and IUI`, [`GIFT and ZIFT`, `IVF and ICSI`, `IUT and GIFT`], `AI and IUI use semen alone (into the vagina or uterus). GIFT moves ova (gametes), ZIFT moves a zygote, IUT moves an embryo, and IVF and ICSI are laboratory fertilisation.`);
mc(5, 'ART', `In a correct IVF sequence for a married couple, the steps are`, `collect ovum and sperm, form zygote in the lab, allow cleavage, then transfer the zygote or embryo`, [`transfer the embryo, then collect sperm, then form the zygote`, `collect the zygote from the uterus, then form the ovum`, `inject the sperm into the uterus, then wait for blastomeres`], `The lab steps come first, followed by transfer. The size of the embryo (up to 8 or more than 8 blastomeres) decides whether it goes into the fallopian tube or the uterus.`);
mc(5, 'contraception', `Progestasert and LNG-20 are alike in being hormone-releasing IUDs. They differ in that`, `Progestasert releases progesterone and LNG-20 releases levonorgestrel, a synthetic progestogen`, [`Progestasert is a copper IUD and LNG-20 is a hormone IUD`, `LNG-20 is non-medicated`, `Progestasert is an oral pill`], `Both are progestogen-type. Progestasert releases the natural-type progesterone; LNG-20 a synthetic progestogen (levonorgestrel). Neither releases copper.`, `Both are in NCERT's hormone-releasing list; the identity of the hormone is a finer detail.`);
mc(5, 'contraception', `Which one is NOT mentioned among the three effects of hormone-releasing contraceptive pills, implants and injectables in NCERT?`, `Killing the ovum in the ovary`, [`Inhibiting ovulation`, `Inhibiting implantation`, `Altering the quality of cervical mucus`], `The three effects are no ovulation, no implantation and a changed cervical mucus. The ovum is never killed in the ovary.`);
mc(5, 'contraception', `A newly married couple wants to delay the first pregnancy for two years and also wants protection against STIs. The most suitable choice is`, `a condom, with a spermicide if wished`, [`tubectomy`, `Copper-T`, `an oral pill alone`], `Only the condom both delays pregnancy (reversible) and protects against STIs. Tubectomy is permanent. Cu-T and the pill do not prevent infection.`, `Some choose a very effective method and forget STI protection.`);
mc(5, 'MTP', `Which of the following is NOT a condition NCERT gives for MTP?`, `Wish of the couple for a baby of a particular sex`, [`Pregnancy due to rape`, `Pregnancy due to failure of a contraceptive method`, `When continuation could be harmful or fatal to the mother or foetus`], `Sex selection is not a valid ground for MTP and is an offence under the law.`);
mc(5, 'population', `Which of the following is a correct reasoning about rapid population growth in the 20th century?`, `Death rate fell more quickly than birth rate`, [`Birth rate rose while death rate rose equally`, `Infant mortality rose while birth rate fell`, `Both death rate and birth rate fell at the same pace`], `If death falls faster than birth, the gap (natural increase) widens, which gives the explosion.`);
mc(5, 'contraception', `The reason why Saheli is considered attractive is`, `it has high contraceptive value with few side effects and is taken weekly`, [`it contains copper and releases it slowly`, `it works by killing sperm in the epididymis`, `it is a surgical method with no reversal`], `NCERT highlights that Saheli, developed by CDRI, is non-steroidal, weekly, with few side effects and high contraceptive value.`);
mc(5, 'ART', `A woman wants to carry a pregnancy but cannot produce ova. Which donation is needed for GIFT?`, `Ova from a donor female`, [`Semen from a donor male only`, `Embryo of 8 blastomeres`, `Fallopian tube`], `GIFT transfers donor ova into the fallopian tube of the recipient, where they meet the husband's sperm. Embryos are used in ZIFT and IUT.`);
mc(5, 'STI', `Which of the following pairs of STIs both are NOT completely curable?`, `Genital herpes and hepatitis-B`, [`Syphilis and gonorrhoea`, `Chlamydiasis and genital warts`, `Trichomoniasis and syphilis`], `NCERT says the exceptions are hepatitis-B, genital herpes and HIV. Here the pair with two of them is correct.`, `Genital warts (HPV) is viral, but NCERT's exception list does not include it.`);
mc(5, 'amniocentesis', `A karyotype from amniocentesis shows 45 chromosomes with a single X. This indicates`, `Turner syndrome`, [`Klinefelter syndrome`, `Down syndrome`, `Patau syndrome`], `Monosomy X (XO, 45 chromosomes) is Turner syndrome. The foetus is a female with underdeveloped ovaries.`);
mc(5, 'contraception', `Why does a condom need to be used "just before coitus" and be disposable?`, `A fresh sheath is needed each time so that it is intact and the semen is held without leakage`, [`It stops the formation of sperm`, `Reuse stimulates ovulation`, `It must dissolve within the body`], `Re-use risks tears and leaks and spreads infection. Condoms hold semen and prevent its entry into the female tract.`);
mc(5, 'surgical', `Which of the following is true for both vasectomy and tubectomy?`, `A small surgical incision is made and the duct (vas deferens or fallopian tube) is cut and tied`, [`The gonads are removed`, `Hormone levels fall to zero`, `Gametes are produced in vitro afterwards`], `Both are terminal methods that block gamete transport. Gonads stay in place, and hormones continue to be made.`);
mc(5, 'ART', `Which statement about embryo transfer after IVF is correct?`, `An embryo with 8 blastomeres goes into the fallopian tube, but one with 16 blastomeres goes into the uterus`, [`All embryos always go into the uterus`, `An embryo with 16 blastomeres goes into the fallopian tube`, `Only the zygote may go into the uterus`], `NCERT sets the limit at 8 blastomeres for the fallopian tube (ZIFT). Anything bigger goes to the uterus (IUT).`);
mc(5, 'population', `Which of the following is a correct statement about India's family planning programme?`, `It began in 1951, and has been expanded into the Reproductive and Child Health Care programme`, [`It began in 1971 with the MTP Act`, `It is limited to male sterilisation`, `It does not cover pre-natal care`], `India's early start (1951) is noted in NCERT. Over time, the programme was broadened to RCH.`);

asr(5, 'ART', `ZIFT and IUT both follow in vitro fertilisation but differ in the site of transfer.`, `ZIFT transfers the zygote or embryo up to 8 blastomeres into the fallopian tube, and IUT transfers embryos with more than 8 blastomeres into the uterus.`, 0, `Both come after IVF. The size of the embryo (8 or fewer blastomeres versus more) decides the site, so R explains A.`);
asr(5, 'contraception', `A woman who has had a tubectomy still produces oestrogen and progesterone.`, `The ovary and uterus are not affected by tubectomy.`, 0, `Cutting the tubes affects gamete transport only. Ovarian hormones continue, and the cycle goes on. R explains A.`);
asr(5, 'MTP', `MTPs are considered safe only in the second trimester of pregnancy.`, `MTPs are relatively safe up to 12 weeks of pregnancy.`, 3, `NCERT says MTPs are safe in the first trimester (up to 12 weeks) and much riskier in the second. So A is false and R is true.`, `The question reverses the NCERT statement in A.`);
stm(5, 'ART', `In AI, semen from a donor may be introduced into the vagina or the uterus.`, `In AI, the ovum is collected from the wife and fertilised outside the body.`, 2, `AI is in vivo fertilisation using semen only. Ovum collection and lab fertilisation belong to IVF. Statement II is incorrect.`);
stm(5, 'contraception', `Lippes loop is a non-medicated IUD, while Multiload 375 releases copper.`, `Progestasert releases copper.`, 2, `Progestasert is hormone-releasing. Statement I is correct; II is incorrect.`);
stm(5, 'contraception', `The first pill of a combined course is started within five days of menstruation.`, `After the 21 days, the next course starts without any gap.`, 2, `A gap of 7 days follows 21 days of pills. Statement II is incorrect.`);

nat(5, 'ART', `Count the techniques that need a donor or wife's ovum to be collected: IVF, ICSI, GIFT, ZIFT, IUI, AI.`, 4, `IVF, ICSI, GIFT and ZIFT use ova (4). IUI and AI use only semen.`);
nat(5, 'contraception', `How many of these are used in emergencies within 72 hours of coitus: progestogen pills, progestogen-oestrogen combinations, IUDs, condoms?`, 3, `NCERT lists progestogens, progestogen-oestrogen combinations and IUDs (3). A condom has to be used before and during coitus.`);

// ===== EXPANSION (round 2) =====
const hm = (level, sub, q, correct, wrongs, sol, trap) => mc(level, sub, q, correct, wrongs, sol, trap, 'statements');
// ---- Level 2
mc(2, 'reproductive health', 'Which of the following is a step towards creating awareness about reproductive health?', 'Sex education in schools', ['Banning all discussion of reproduction', 'Giving no information until marriage', 'Hiding the facts of adolescence from students'], 'Introducing sex education in schools helps to provide correct information and to break myths and misconceptions about sex-related aspects.');
mc(2, 'reproductive health', 'A reproductively healthy society needs which of the following?', 'People with physically and functionally normal reproductive organs, and with emotional and behavioural interactions among them in all sex-related aspects', ['Only large families', 'Only the absence of disease', 'Only high income'], 'The WHO describes reproductive health as total well-being in all aspects of reproduction: physical, emotional, behavioural and social.');
mc(2, 'contraception', 'The contraceptive brand "Nirodh" is a popular brand of', 'condoms', ['oral pills', 'IUDs', 'injectables'], 'Nirodh is a well-known brand of condom, a barrier method.');
mc(2, 'contraception', 'Diaphragms, cervical caps and vaults are barriers that', 'cover the cervix in the female reproductive tract, and prevent sperm from reaching the ovum', ['are worn on the penis', 'are placed under the skin', 'are taken as pills'], 'They are made of rubber and inserted into the female tract to cover the cervix before coitus. Their reusability is a feature.');
mc(2, 'contraception', 'Which of the following is a non-medicated IUD?', 'Lippes loop', ['Cu7', 'LNG-20', 'Multiload 375'], 'Non-medicated IUDs include the Lippes loop. Cu7 and Multiload 375 release copper; Progestasert and LNG-20 release hormones.');
mc(2, 'contraception', 'Which of the following IUDs releases copper ions?', 'Multiload 375', ['Lippes loop', 'Progestasert', 'LNG-20'], 'Copper-releasing IUDs are CuT, Cu7 and Multiload 375. Progestasert and LNG-20 release hormones.');
mc(2, 'contraception', 'Periodic abstinence means avoiding coitus from day', '10 to 17 of the menstrual cycle', ['1 to 5 of the cycle', '20 to 28 of the cycle', '5 to 10 of the cycle'], 'Ovulation is expected during days 10 to 17, so this is the fertile period. Natural methods work by avoiding the chance of meeting of the ovum and sperm.');
mc(2, 'contraception', 'The withdrawal method (coitus interruptus) involves', 'withdrawal of the penis from the vagina just before ejaculation', ['using a rubber sheath', 'taking a pill every week', 'inserting an IUD'], 'The male withdraws before ejaculation so that semen is not deposited in the vagina.');
mc(2, 'contraception', 'The pill Saheli is taken', 'once a week', ['daily for 21 days', 'once a month', 'after every coitus'], 'Saheli is a non-steroidal pill developed at CDRI, Lucknow. It has few side effects and a high contraceptive value.');
mc(2, 'surgical', 'In vasectomy a small part of the vas deferens is removed or tied through an incision in the', 'scrotum', ['abdomen', 'vagina', 'thigh'], 'In tubectomy, the incision is made in the abdomen or through the vagina. In vasectomy it is on the scrotum.');
mc(2, 'STI', 'Which of the following is a viral sexually transmitted infection?', 'Genital herpes', ['Gonorrhoea', 'Syphilis', 'Chlamydiasis'], 'Genital herpes, hepatitis-B, HIV and genital warts are viral. Gonorrhoea, syphilis and chlamydiasis are bacterial; trichomoniasis is caused by a protozoan.');
mc(2, 'STI', 'Which of the following is caused by a protozoan?', 'Trichomoniasis', ['Gonorrhoea', 'Genital herpes', 'Hepatitis-B'], 'Trichomoniasis is caused by Trichomonas vaginalis, a protozoan. Gonorrhoea and syphilis are bacterial; herpes and hepatitis B are viral.');
mc(2, 'MTP', 'MTP is relatively safe during the first', '12 weeks of pregnancy', ['24 weeks of pregnancy', '36 weeks of pregnancy', '4 weeks after delivery'], 'MTP up to 12 weeks (first trimester) is relatively safe. The second trimester is very risky.');
mc(2, 'ART', 'The first "test-tube baby" technique involves fertilisation', 'outside the body, in the laboratory', ['inside the uterus', 'in the fallopian tube in vivo', 'in the vagina'], 'In IVF, fertilisation takes place in vitro under laboratory conditions similar to the body, and the embryo is then transferred.');

// ---- Level 3
mc(3, 'contraception', 'A woman with a 28-day cycle starts a combined pill on day 5 and takes one daily for 21 days. On which day of her cycle does she take the last pill?', 'Day 25', ['Day 21', 'Day 26', 'Day 28'], 'Day 5 is the first pill. The 21st pill is on day 5 + 20 = day 25.', 'Count the first day as one.');
mc(3, 'contraception', 'After the 21 pills, the 7-day gap is followed by a new course, which should start', 'on the day after the 7-day gap, again around the fifth day of the next cycle', ['at once without a gap', 'after a month-long gap', 'only if menstruation fails'], 'The pills are taken for 21 days, then there is a gap of 7 days when menstruation occurs, and then the course is repeated.');
mc(3, 'contraception', 'Which of these is NOT a way in which hormonal contraceptive methods work?', 'Increase in sperm production', ['Inhibition of ovulation', 'Inhibition of implantation', 'Altering the quality of cervical mucus to prevent sperm entry'], 'Hormone-containing pills, injectables and implants prevent ovulation and implantation, and alter the cervical mucus so that it impedes the sperm entry.');
mc(3, 'contraception', 'IUDs that release copper ions are effective because the ions', 'suppress the motility and the fertilising capacity of sperms', ['stop ovulation', 'make the cervix produce eggs', 'kill the ovum before ovulation'], 'Cu ions released by the Cu-IUD reduce the sperm motility and fertilising capacity.');
mc(3, 'contraception', 'IUDs are ideal contraceptives for females who', 'want to delay pregnancy or space children', ['want permanent protection', 'are lactating only', 'are in the first trimester'], 'IUDs are reversible, effective, and widely accepted by females for delaying and spacing pregnancies.');
mc(3, 'contraception', 'Emergency contraceptives such as progestogen pills or IUDs can be used within', '72 hours of coitus', ['72 days of coitus', '7 days before coitus', '30 days after coitus'], 'The administration of progestogens or progestogen-oestrogen combinations or IUDs within 72 hours of coitus has been found to be effective as emergency contraception for avoiding possible pregnancy due to rape or casual unprotected intercourse.');
mc(3, 'contraception', 'Which of these is a barrier method used by males?', 'Condom', ['Diaphragm', 'Cervical cap', 'Vaults'], 'The condom is used by the male (and a female condom exists too). Diaphragms, caps and vaults are female barriers.');
mc(3, 'contraception', 'Which of the following helps to prevent STIs as well as pregnancy?', 'Condom', ['Oral pills', 'Cu-T', 'Implants'], 'Condoms are barriers for sperm and for infectious organisms. The hormonal methods and IUDs do not protect against STIs.');
mc(3, 'contraception', 'A breast-feeding mother who has not resumed her menstrual cycle has a low chance of pregnancy for up to', 'a maximum of six months after delivery', ['two years after delivery', 'one month after delivery', 'one week after delivery'], 'During the period of intense lactation after parturition, there is absence of menstruation (lactational amenorrhoea). There is almost no chance of conception during this period, up to a maximum of six months following parturition.');
mc(3, 'surgical', 'The surgical methods of contraception are also called', 'sterilisation', ['natural methods', 'barrier methods', 'emergency contraceptives'], 'Sterilisation procedures are generally advised for the male or the female partner as a terminal method to prevent any more pregnancies.');
mc(3, 'surgical', 'Tubectomy blocks the passage of', 'ova to the uterus, so that the sperm and ovum cannot meet', ['sperm through the urethra', 'blood in the uterus', 'urine'], 'Tubectomy removes or ties a small part of the fallopian tube. Vasectomy blocks the vas deferens so that sperm cannot be ejaculated.');
mc(3, 'ART', 'ZIFT transfers', 'a zygote or an early embryo with up to 8 blastomeres into the fallopian tube', ['an embryo with more than 8 blastomeres into the fallopian tube', 'a sperm into the uterus', 'an ovum into the vagina'], 'ZIFT stands for zygote intra-fallopian transfer. IUT is the transfer of an embryo with more than 8 blastomeres into the uterus.');
mc(3, 'ART', 'IUT stands for', 'intra-uterine transfer', ['intra-urethral transfer', 'in-utero treatment', 'intra-uterine test'], 'In IUT, embryos with more than 8 blastomeres are transferred into the uterus, to complete their development.');
mc(3, 'ART', 'GIFT involves the transfer of', 'an ovum collected from a donor into the fallopian tube of another female who cannot produce ova but can provide a suitable environment for fertilisation and development', ['a zygote into the vagina', 'sperm into the stomach', 'an embryo to an incubator'], 'GIFT is gamete intra-fallopian transfer. Fertilisation occurs in vivo.');
mc(3, 'ART', 'ICSI, a type of ART, means', 'injecting a sperm directly into an ovum', ['injecting an ovum into the uterus', 'transferring the embryo into the vagina', 'removing the ovum'], 'Intra-cytoplasmic sperm injection helps in cases where the male partner has very low sperm count.');
mc(3, 'ART', 'IUI, intra-uterine insemination, is a technique in which', 'the semen of the husband or a healthy donor is introduced into the uterus', ['the zygote is placed in the uterus', 'the ovum is injected with sperm', 'the embryo is stored in a freezer'], 'In artificial insemination (AI), the semen is introduced either into the vagina or into the uterus (IUI). It helps when the male cannot inseminate or has a low sperm count.');
mc(3, 'ART', 'In IVF, the zygote or early embryos with up to 8 blastomeres are transferred into the', 'fallopian tube (ZIFT)', ['stomach', 'vagina', 'urinary bladder'], 'ZIFT places the early embryo into the fallopian tube; those with more than 8 blastomeres are placed into the uterus.');
mc(3, 'STI', 'Which of the following STIs can also spread by sharing of injection needles and blood transfusion?', 'Hepatitis-B and HIV', ['Gonorrhoea and syphilis only', 'Genital warts only', 'Chlamydiasis only'], 'Besides sexual contact, hepatitis-B and HIV can spread through sharing of injection needles, surgical instruments, blood transfusion and from an infected mother to the foetus.');
mc(3, 'STI', 'Which of these is a preventive measure for STIs?', 'Always using condoms during coitus', ['Having multiple partners', 'Sharing needles', 'Ignoring early symptoms'], 'Avoid sex with unknown partners or multiple partners, use condoms, and seek medical help early if infection is suspected.');
mc(3, 'STI', 'Which of the following is NOT an STI?', 'Malaria', ['Syphilis', 'Gonorrhoea', 'Genital herpes'], 'Malaria is caused by Plasmodium and is spread by mosquitoes. The others are STIs.');
mc(3, 'amniocentesis', 'Amniocentesis can detect', 'chromosomal abnormalities such as Down syndrome, and disorders like haemophilia and sickle-cell anaemia', ['only the blood group of the baby', 'only the age of the foetus', 'only twin pregnancy'], 'It is a pre-natal diagnostic technique in which the amniotic fluid is tested for foetal cells. It is used to detect chromosomal and metabolic disorders; it is banned for sex determination.');
mc(3, 'amniocentesis', 'Why is amniocentesis for sex determination banned?', 'It has been misused for female foeticide', ['It always harms the mother', 'It cannot detect any disorders', 'It only works in animals'], 'A statutory ban has been enforced to prevent female foeticide, and to prevent the sex ratio from falling.');
mc(3, 'infertility', 'Infertility is the inability to produce children even after', 'unprotected sexual cohabitation', ['use of contraceptives', 'vasectomy', 'menopause only'], 'Infertility may be due to physical, congenital, diseases, drugs, immunological or psychological causes.');
mc(3, 'population', 'Which of the following has contributed to the population explosion?', 'A decline in the death rate, the maternal mortality rate and infant mortality rate, and an increase in the number of people in the reproductive age', ['An increase in infant mortality', 'A decrease in the number of people in the reproductive age', 'A rise in the death rate'], 'Better health care and living conditions reduced mortality, and more people of reproductive age increased births.');
mc(3, 'population', 'The statutory marriageable age for females and males in India is respectively', '18 years and 21 years', ['21 years and 18 years', '18 years and 18 years', '16 years and 18 years'], 'The marriageable age was set at 18 for females and 21 for males to help control the birth rate.');
asr(3, 'contraception', 'Copper-releasing IUDs act as contraceptives.', 'The copper ions suppress sperm motility and the fertilising capacity of sperms.', 0, 'Copper ions released by the IUD reduce sperm function; this explains the contraceptive action.');
asr(3, 'contraception', 'Lactational amenorrhoea is a reliable contraceptive method for an unlimited period.', 'There is no menstruation during lactation.', 3, 'A is false. It is effective only up to a maximum of six months after parturition. R is true.', 'It is time-limited.');
asr(3, 'ART', 'ICSI is useful in some cases of male infertility.', 'A single sperm is injected into the ovum.', 0, 'A sperm injected directly into the ovum bypasses the need for the sperm to swim and penetrate, helping men with very low sperm counts. R explains A.');
asr(3, 'MTP', 'MTP is legal in India.', 'It was legalised in 1971 with some strict conditions to avoid its misuse.', 0, 'MTP is legal under the Act of 1971, with conditions. R explains A.');
stm(3, 'contraception', 'Oral pills can contain progestogens alone.', 'Oral pills can contain a combination of progestogen and oestrogen.', 0, 'Both are correct.');
stm(3, 'ART', 'In ZIFT the embryo is transferred into the uterus.', 'In IUT the embryo is transferred into the fallopian tube.', 1, 'Both are wrong: ZIFT is into the fallopian tube and IUT is into the uterus.', 'Do not swap the sites.');
stm(3, 'surgical', 'Tubectomy involves cutting or tying of the fallopian tubes.', 'Vasectomy involves cutting or tying of the vasa deferentia.', 0, 'Both are correct.');
hm(3, 'contraception', 'Consider the following. (1) Condom is a barrier. (2) IUD is inserted into the uterus. (3) Saheli is taken daily. (4) Vasectomy is a surgical method. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (4) are correct. (3) is wrong: Saheli is taken once a week.');
hm(3, 'STI', 'Consider the following STIs. (1) Gonorrhoea (2) Syphilis (3) Chlamydiasis (4) Genital herpes. How many are bacterial in origin?', 'Three', ['Two', 'One', 'All four'], 'Gonorrhoea, syphilis and chlamydiasis are bacterial. Genital herpes is viral.');
match(3, 'contraception', 'xm1', 'Contraceptive and type', ['A. Lippes loop', 'B. Saheli', 'C. Condom', 'D. Vasectomy'], ['p. Non-medicated IUD', 'q. Non-steroidal oral pill', 'r. Barrier method', 's. Surgical method'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Lippes loop is an IUD; Saheli is non-steroidal; condoms are barriers; vasectomy is surgical.');
match(3, 'ART', 'xm2', 'Technique and meaning', ['A. IVF', 'B. ZIFT', 'C. GIFT', 'D. ICSI'], ['p. Fertilisation in the laboratory', 'q. Transfer of zygote into the fallopian tube', 'r. Transfer of gametes into the fallopian tube', 's. Injection of a sperm into an ovum'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'IVF is in vitro fertilisation; ZIFT transfers a zygote; GIFT transfers gametes; ICSI is direct injection of a sperm.');
match(3, 'STI', 'xm3', 'STI and causative agent', ['A. Syphilis', 'B. Gonorrhoea', 'C. Genital herpes', 'D. Trichomoniasis'], ['p. Treponema pallidum, a bacterium', 'q. Neisseria gonorrhoeae, a bacterium', 'r. Herpes simplex virus', 's. A protozoan'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Syphilis: Treponema; gonorrhoea: Neisseria; herpes: a virus; trichomoniasis: Trichomonas, a protozoan.');
nat(3, 'contraception', 'A woman takes the combined pill for 21 days, then has a gap of 7 days, and repeats this pattern. How many pills does she take in 12 complete courses?', 252, '12 courses x 21 pills = 252 pills. The 7-day gaps have no pills.', 'pills', 'The gap days have no pills.');
nat(3, 'contraception', 'Periodic abstinence is advised from day 10 to day 17 of the cycle (both days included). How many days of abstinence is this in one cycle?', 8, 'Days 10 to 17 inclusive: 17 - 10 + 1 = 8 days.', 'days', 'Count both end days.');

// ---- Level 4
mc(4, 'contraception', 'A couple who have just had a baby want to space the next pregnancy by about two years and also want something that is reversible and without daily action. The best option is', 'an IUD', ['vasectomy', 'tubectomy', 'a daily pill'], 'IUDs are reversible, long-acting and need no daily action. Sterilisation is terminal; the pill needs daily use.');
mc(4, 'contraception', 'Which statement about the hormonal IUDs such as LNG-20 is correct?', 'They make the uterus unsuitable for implantation and the cervix hostile to sperm', ['They release copper ions that kill the zygote', 'They are non-medicated', 'They are taken orally'], 'Hormone-releasing IUDs (Progestasert, LNG-20) make the uterus unsuitable for implantation and the cervix hostile to the sperm.');
mc(4, 'contraception', 'Both copper-releasing and hormone-releasing IUDs share which of these?', 'They are inserted by a doctor or trained nurse into the uterus through the vagina', ['They are taken daily by mouth', 'They protect against HIV', 'They are placed under the skin'], 'IUDs are inserted into the uterus through the vagina; they do not protect against STIs.');
mc(4, 'contraception', 'Which of these correctly shows a difference between implants and oral pills?', 'Implants are placed under the skin and act for a long time, while pills are taken daily', ['Implants contain copper, pills do not', 'Implants protect from STIs, pills do not', 'Implants are non-hormonal'], 'Implants and injectables are used by females and are hormonal, with the same effect as the pills but longer duration.');
mc(4, 'contraception', 'The reason for using spermicidal jelly with diaphragms is to', 'add a chemical barrier that kills or immobilises sperm', ['strengthen the rubber', 'prevent infections of the cervix', 'raise the temperature'], 'Spermicidal creams, jellies and foams are usually used along with these barriers to increase their contraceptive efficiency.');
mc(4, 'contraception', 'A female condom is different from a male condom in that it', 'lines the vagina and cervix and can be used by the female', ['is worn on the penis', 'releases hormones', 'is inserted into the uterus'], 'Condoms are made of thin rubber/latex sheath, and are used to cover the penis in the male or vagina and cervix in the female just before coitus.');
mc(4, 'surgical', 'Sterilisation is NOT recommended for couples who', 'wish to have children later, because it is difficult to reverse', ['already have the number of children they want', 'are in a stable marriage', 'have completed the family'], 'Sterilisation methods are terminal. Reversal is very poor; thus they are chosen by couples who do not want more children.');
mc(4, 'MTP', 'Why are MTPs after the first trimester not safe?', 'The foetus becomes intimately associated with the maternal tissues and the risk to the mother is high', ['The foetus is too small', 'The mother cannot be given anaesthesia', 'The placenta has not formed'], 'In the second trimester, the foetus is intimately associated with maternal tissues. This makes the procedure very risky.');
mc(4, 'MTP', 'Which of these is NOT among the reasons for which MTPs are done?', 'Desire to have a boy rather than a girl', ['Unplanned pregnancy due to failure of contraceptives', 'Pregnancies due to rape', 'Pregnancies harmful to the mother or the foetus'], 'MTP was legalised with strict conditions. Sex-selective abortion is illegal.');
mc(4, 'amniocentesis', 'A foetus is found by amniocentesis to have 47 chromosomes with an extra chromosome 21. The condition is', 'Down syndrome', ['Turner syndrome', 'Klinefelter syndrome', 'haemophilia'], 'Trisomy 21 gives Down syndrome. Turner is XO (45); Klinefelter is XXY (47).');
mc(4, 'amniocentesis', 'In amniocentesis, the fluid taken is tested for', 'the foetal cells shed into it, which can be analysed for chromosomes and metabolic disorders', ['only the mother\'s blood cells', 'the foetal heartbeat', 'the pH of the uterus'], 'The amniotic fluid surrounding the developing embryo contains foetal cells and dissolved substances that can be analysed.');
mc(4, 'ART', 'A woman has blocked fallopian tubes but healthy ova and uterus. Which of the following ARTs is most suitable?', 'IVF followed by embryo transfer into the uterus (IUT)', ['ZIFT, transferring to the blocked tubes', 'GIFT, transferring gametes into the blocked tubes', 'Artificial insemination into the vagina'], 'Transfer into a blocked fallopian tube cannot work. IVF with transfer of an embryo with more than 8 blastomeres into the uterus bypasses the block.', 'Check which tube-based methods are useless when the tubes are blocked.');
mc(4, 'ART', 'A couple has a husband with a very low sperm count, but the wife is normal. Which of the following would be the most direct way to bring about fertilisation?', 'ICSI', ['Tubectomy', 'GIFT with donor sperm only', 'Hormone pills'], 'Direct injection of a sperm into the ovum bypasses the need for many sperm. AI/IUI is also possible.');
mc(4, 'ART', 'A couple wants a child; the male cannot ejaculate normally into the vagina. Which method suits?', 'Artificial insemination using his semen', ['Tubectomy', 'GIFT', 'Vasectomy'], 'AI introduces the semen artificially into the vagina or the uterus.');
mc(4, 'ART', 'Which of these does NOT involve the transfer of a developing embryo?', 'AI', ['ZIFT', 'IUT', 'IVF-ET'], 'AI introduces semen only. ZIFT, IUT and IVF-ET all transfer a zygote or embryo.');
mc(4, 'infertility', 'A couple can choose adoption when', 'all ART methods fail or are not suitable', ['a woman is fertile and has a child', 'ART methods are always successful', 'contraceptives work'], 'For childless couples, adoption is a solution, according to NCERT, when ART does not help.');
mc(4, 'STI', 'A major reason for the spread of STIs in adolescents is', 'lack of awareness and delay in seeking treatment because symptoms may be mild', ['immunisation against them', 'use of condoms', 'a high fever'], 'The infections often have mild or no symptoms, so people neglect them, leading to complications such as PID, abortions, still births, infertility, and cancer of the reproductive tract.');
mc(4, 'STI', 'Which of the following is a possible complication of untreated STIs in females?', 'Pelvic inflammatory disease, ectopic pregnancy and infertility', ['Faster ovulation', 'Increased fertility', 'Menopause at 20'], 'NCERT lists PID, abortions, still births, ectopic pregnancies, infertility and even cancer of the reproductive tract.');
mc(4, 'population', 'The worldwide population was about 2 billion in 1900 and rose to about', '6 billion by 2000', ['3 billion by 2000', '4 billion by 1950', '10 billion by 2000'], 'NCERT notes the population rose from 2 billion in 1900 to about 6 billion in 2000, and India reached about 1 billion by 2000.');
mc(4, 'population', 'An effective way of reducing population growth that is discussed in NCERT is', 'motivating small families with one or two children', ['raising the death rate', 'banning marriages', 'increasing the marriageable age to 50'], 'Some incentives are offered to couples with small families. The statutory marriageable age (18 for females, 21 for males) also helps.');
asr(4, 'ART', 'ZIFT and IUT are both used after in vitro fertilisation.', 'In both techniques the embryo is formed in the laboratory.', 0, 'In both the fertilisation is in the lab, and an embryo is then transferred to the female. R explains A.');
asr(4, 'ART', 'GIFT is considered an in vivo fertilisation method.', 'In GIFT the fertilisation takes place inside the female body.', 0, 'The gametes are placed into the fallopian tube, where fertilisation takes place. R explains A.');
asr(4, 'contraception', 'Oral pills are NOT a good way to protect against STIs.', 'Pills contain hormones that stop ovulation but do not act as a barrier to microbes.', 0, 'Only a barrier method physically stops contact. R explains A.');
asr(4, 'surgical', 'After vasectomy a man still produces testosterone.', 'Vasectomy blocks only the vasa deferentia and does not affect the testes\' hormone secretion.', 0, 'Testes continue to produce testosterone, which goes in the blood, so secondary sexual features and desire are normal. R explains A.');
asr(4, 'MTP', 'MTP is relatively safe in the first 12 weeks of pregnancy.', 'During this period the foetus is not yet intimately associated with maternal tissues.', 0, 'Later in pregnancy, the foetus is intimately associated with maternal tissues, which makes MTP risky. R explains A.');
stm(4, 'contraception', 'Hormonal implants are placed under the skin.', 'Implants act for a very short period of a day only.', 2, 'Implants are under the skin and act for a long time. Statement II is wrong.');
stm(4, 'ART', 'In IVF, the ova of the wife or a donor are induced to form zygotes in the laboratory.', 'The zygote is formed in the laboratory with sperm from the husband or a donor.', 0, 'Both are correct.');
stm(4, 'STI', 'All STIs are completely curable if detected early.', 'Hepatitis-B, genital herpes and HIV are not completely curable.', 3, 'Statement I is too general: NCERT notes exceptions (hepatitis-B, genital herpes and HIV). Statement II is correct.', 'Look for the word "all".');
hm(4, 'ART', 'Consider the following. (1) ZIFT places the zygote in the fallopian tube. (2) IUT places an embryo of more than 8 blastomeres in the uterus. (3) GIFT is done by transfer of an embryo. (4) AI introduces semen. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (4) are correct. GIFT is the transfer of gametes (an ovum), not an embryo.');
hm(4, 'contraception', 'Consider the following. (1) Cu-T releases copper ions. (2) Lippes loop is non-medicated. (3) LNG-20 is a hormone releasing IUD. (4) Saheli is taken daily. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. Saheli is taken once a week.');
match(4, 'contraception', 'xm4', 'Method and how it prevents pregnancy', ['A. Condom', 'B. Cu-T', 'C. Pills', 'D. Tubectomy'], ['p. Prevents entry of sperm into the female tract', 'q. Suppresses sperm motility and fertilising capacity', 'r. Inhibits ovulation and implantation, alters cervical mucus', 's. Blocks the passage of ova to the uterus'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'A condom is a barrier; Cu-T acts on sperm; pills prevent ovulation and implantation; tubectomy blocks the fallopian tubes.');
match(4, 'ART', 'xm5', 'ART and condition for which it is suited', ['A. IUI', 'B. ICSI', 'C. GIFT', 'D. IUT'], ['p. Male unable to inseminate or low sperm count', 'q. Male has very few sperm; sperm injected into ovum', 'r. Female cannot produce ova but can support development', 's. Embryo with more than 8 blastomeres transferred to uterus'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'IUI helps when the male cannot inseminate or has a low sperm count; ICSI deals with very few sperm; GIFT uses a donor ovum; IUT transfers a later embryo to the uterus.');
match(4, 'population', 'xm7', 'Item and value in NCERT', ['A. Statutory marriageable age for females', 'B. Statutory marriageable age for males', 'C. Safe period for MTP', 'D. Period of lactational amenorrhoea protection'], ['p. 18 years', 'q. 21 years', 'r. Up to 12 weeks', 's. Up to six months'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Female 18, male 21, MTP safe up to 12 weeks, lactational amenorrhoea up to 6 months.');
pass('xp1', 'Passage: choosing a method', 'A newly married couple, both 25, want to postpone the first child for two years. They want a method that is reversible, does not need daily action, and that the wife can use without interrupting intercourse. Another couple with three children want no more children and prefer a permanent method.');
pq('xp1', 3, 'contraception', 'For the first couple, the most suitable method is', 'an IUD', ['vasectomy', 'tubectomy', 'withdrawal only'], 'IUDs are reversible, long-acting and do not need action at the time of coitus.');
pq('xp1', 4, 'surgical', 'For the second couple, a suitable option is', 'vasectomy or tubectomy', ['an IUD only', 'periodic abstinence only', 'lactational amenorrhoea'], 'Surgical sterilisation is a terminal method.');
pq('xp1', 4, 'contraception', 'Neither of the two methods chosen protects against', 'STIs', ['pregnancy', 'ovulation', 'implantation'], 'IUDs and sterilisation do not prevent the spread of STIs. A condom does.');
pass('xp2', 'Passage: an ART clinic', 'A clinic describes three cases. Case P: the wife produces no ova but has a healthy uterus and tubes. Case Q: the husband has a very low sperm count. Case R: the husband cannot ejaculate normally in the vagina but has normal semen.');
pq('xp2', 3, 'ART', 'The best match for Case R is', 'artificial insemination', ['GIFT', 'tubectomy', 'ICSI'], 'AI introduces the semen of the husband into the vagina or uterus.');
pq('xp2', 4, 'ART', 'The best match for Case P is', 'GIFT with an ovum from a donor', ['AI alone', 'vasectomy', 'ICSI with her own ovum'], 'GIFT transfers a donor ovum into the fallopian tube of a female who cannot produce ova but provides a suitable environment.');
pass('xp3', 'Passage: population data', 'In a country the population was 350 million at the start of a period and 1000 million 53 years later. Over the same time infant mortality and maternal mortality fell sharply, and the number of persons of reproductive age rose.');
pq('xp3', 3, 'population', 'The main reason for the rapid rise is', 'a fall in death rates, MMR and IMR, together with more people in the reproductive age', ['a fall in birth rate', 'a rise in infant mortality', 'a decline in marriages'], 'The fall in mortality and a larger reproductive age group increase the population.');
pq('xp3', 4, 'population', 'The population increased by what factor, approximately?', 'About 2.9 times', ['About 1.4 times', 'About 10 times', 'About 5 times'], '1000/350 = 2.86, about 2.9 times.');
pq('xp3', 4, 'population', 'Which measure would help to slow the growth?', 'Small families, birth control, and a statutory minimum marriageable age', ['Higher infant mortality', 'No contraceptives', 'Earlier marriages'], 'These are the measures suggested by NCERT.');

// ---- Level 5
mc(5, 'contraception', 'A woman takes the combined pill daily for 21 days, starting on day 5 of her cycle, and then stops for 7 days. Menstruation takes place', 'during the 7-day gap', ['on the 10th day of pills', 'only after taking the pills for a year', 'never'], 'During the gap the hormone level falls and menstruation takes place.');
mc(5, 'surgical', 'After a tubectomy a woman', 'continues to ovulate and produce hormones, but the ovum cannot reach the sperm', ['stops producing oestrogen', 'cannot menstruate', 'loses her ovaries'], 'The ovaries are untouched. The ovum cannot reach the uterus, and the sperm cannot reach the ovum.');
mc(5, 'surgical', 'Which of the following statements is true for both vasectomy and tubectomy?', 'Both are terminal methods that do not affect sex hormone production', ['Both stop hormone production', 'Both can be easily reversed with 100 per cent success', 'Both protect against STIs'], 'Gonads are not removed; hormones continue. Neither protects from STIs.');
mc(5, 'ART', 'In IVF, which of the following is an essential step?', 'Fertilisation of the ovum with sperm in the laboratory and transfer of the embryo', ['Removal of both ovaries', 'Vasectomy of the husband', 'Placing the sperm in the stomach'], 'IVF requires an ovum, sperm, fertilisation in vitro, and transfer of the zygote or embryo into the female tract.');
mc(5, 'ART', 'An embryo of 16 blastomeres is formed in the laboratory. It should be transferred into the', 'uterus (IUT)', ['fallopian tube (ZIFT)', 'vagina', 'ovary'], 'Embryos with more than 8 blastomeres are transferred into the uterus; those with up to 8 blastomeres can be put into the fallopian tube.');
mc(5, 'ART', 'Which pair of ART methods both involve in vivo fertilisation?', 'GIFT and AI', ['ZIFT and IUT', 'IVF and ICSI', 'ICSI and ZIFT'], 'GIFT and AI let fertilisation occur inside the female body. IVF, ICSI, ZIFT and IUT all involve fertilisation outside.');
mc(5, 'STI', 'Which of the following correctly differentiates HIV from gonorrhoea?', 'HIV is viral and can spread through blood, whereas gonorrhoea is bacterial and mainly sexual', ['Both are caused by bacteria', 'HIV is curable with antibiotics', 'Gonorrhoea is viral'], 'Gonorrhoea is bacterial and curable. HIV is viral and not completely curable.');
mc(5, 'population', 'Which statement about India\'s population policy in NCERT is correct?', 'Reproductive health programmes aim at a small family norm, with a statutory minimum marriageable age and incentives', ['India has no family planning programme', 'The ban on amniocentesis is to increase the population', 'The marriageable age is the same for males and females'], 'Family planning started in 1951; there are incentives for small families, and statutory minimum ages of marriage.');
asr(5, 'ART', 'In ZIFT the zygote is transferred into the fallopian tube, and it is an in vitro method.', 'The zygote is formed in the laboratory before the transfer.', 0, 'Fertilisation is in vitro and the zygote is moved to the female tract. R explains A.');
stm(5, 'surgical', 'Vasectomy is a surgical contraceptive method used by males.', 'The vasa deferentia are cut or tied, and the sperm cannot be ejaculated with semen.', 0, 'Both correct.');
stm(5, 'ART', 'GIFT and AI both lead to fertilisation inside the body.', 'IUT leads to fertilisation inside the uterus.', 2, 'GIFT and AI: in vivo fertilisation (I correct). IUT transfers an embryo already formed in the lab (II incorrect).');
hm(5, 'contraception', 'Consider the following. (1) Pills stop ovulation. (2) Cu-T stops sperm motility. (3) A condom prevents entry of sperm. (4) Implants are placed in the uterus. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. Implants are placed under the skin.');
hm(5, 'ART', 'Consider the following. (1) IVF-ET (2) ZIFT (3) IUT (4) AI. How many involve in vitro fertilisation?', 'Three', ['Two', 'One', 'All four'], 'IVF-ET, ZIFT and IUT involve fertilisation in the laboratory. AI leads to natural in vivo fertilisation.');
match(5, 'contraception', 'xm8', 'Method and its duration of action per administration', ['A. Condom', 'B. Combined pill (21-day course)', 'C. Saheli', 'D. IUD'], ['p. One act of coitus', 'q. One day', 'r. One week', 's. Long term, years'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'A condom is used for each act; the combined pill is taken daily; Saheli is weekly; an IUD is left in for years.');
match(5, 'ART', 'xm9', 'Technique and site where the transfer or introduction happens', ['A. ZIFT', 'B. IUT', 'C. GIFT', 'D. AI'], ['p. Fallopian tube (zygote)', 'q. Uterus (embryo with more than 8 blastomeres)', 'r. Fallopian tube (gametes)', 's. Vagina or uterus (semen)'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'ZIFT: zygote into the fallopian tube. IUT: embryo into the uterus. GIFT: gametes into the fallopian tube. AI: semen into the vagina or uterus.');
match(5, 'STI', 'xm10', 'Disease and causative organism', ['A. Genital warts', 'B. Hepatitis-B', 'C. Chlamydiasis', 'D. Trichomoniasis'], ['p. Human papilloma virus', 'q. Hepatitis B virus', 'r. Chlamydia trachomatis', 's. Trichomonas vaginalis'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Genital warts: HPV (virus). Hepatitis-B: HBV (virus). Chlamydiasis: Chlamydia (bacterium). Trichomoniasis: Trichomonas (protozoan).');
match(4, 'contraception', 'xm11', 'Category and example', ['A. Non-medicated IUD', 'B. Copper-releasing IUD', 'C. Hormone-releasing IUD', 'D. Emergency contraceptive'], ['p. Lippes loop', 'q. Multiload 375', 'r. LNG-20', 's. Progestogen pills within 72 hours of coitus'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Lippes loop is non-medicated, Multiload 375 releases copper, LNG-20 releases hormone; emergency contraception uses progestogens or IUDs within 72 hours.');

export default { topic: 'reproductive-health', groups, items, gens: [] };
